// Shared constants and types for Mower Chain. READ-ONLY for workers: every module imports from here.
// Coordinates: world units, x right, y down, origin top-left, world is WORLD_SIZE x WORLD_SIZE. Angles in radians (0 = +x, clockwise on screen).

export const SCENES = { boot: 'Boot', title: 'Title', game: 'Game' } as const;

/** Texture keys generated by textures.ts makeTextures(scene). */
export const TEX = {
  head: 'mc-head',       // 48x48, mower seen from above facing +x, drawn WHITE-tinted-able (deck is white so setTint(color) colours it)
  body: 'mc-body',       // 40x40, a trailing mower segment facing +x, same tint rule
  grass: 'mc-grass',     // 16x16 grass tuft pellet
  gold: 'mc-gold',       // 24x24 golden clipping pellet (dropped by dead mowers)
  tile: 'mc-tile',       // 128x128 seamless lawn tile with mow stripes, for a TileSprite background
} as const;

/** Tuning. Change these to change the feel. */
export const TUNING = {
  WORLD_SIZE: 4000,
  START_SEGS: 5,            // body segments (not counting the head) at spawn
  SEG_SPACING: 22,          // distance between consecutive segments along the trail
  HEAD_R: 18,               // collision radius of a head
  SEG_R: 15,                // collision radius of a body segment
  SPEED: 190,               // units/s
  BOOST_SPEED: 340,
  TURN_RATE: 4.2,           // max radians/s the heading turns toward the wanted angle
  BOOST_COST: 3,            // score lost per second while boosting (a gold-less grass pellet drops behind every 0.25 s)
  MIN_BOOST_SCORE: 10,      // cannot boost below this score
  SCORE_PER_SEG: 4,         // body segments = START_SEGS + floor(score / SCORE_PER_SEG)
  MAX_SEGS: 400,
  PELLET_COUNT: 450,        // grass pellets kept in the world
  PELLET_R: 14,             // pickup radius (added to HEAD_R)
  GRASS_VALUE: 1,
  GOLD_VALUE: 5,
  DEATH_DROP_FRACTION: 0.7, // of a dead mower's score that spills as gold pellets (one per few segments)
  SPAWN_MARGIN: 300,        // spawn at least this far from the world edge
  RESPAWN_PROTECT_S: 2,     // invulnerable (and blinking) after spawn
  BOT_TARGET: 14,           // host keeps humans + bots at this many mowers
  SIM_HZ: 30,               // host simulation step
  SNAP_HZ: 15,              // host snapshot send rate
  INPUT_HZ: 20,             // client input send rate
  VIEW_UNITS: 1100,         // world units visible across the shorter screen side at length 0 (camera zoom out as you grow, see GameScene)
} as const;

export const HELLO_GAME = 'mower-chain' as const;

/** One mower chain as shown to every client. */
export interface MowerSnap {
  id: number;               // player id from the server for humans; bots use negative ids (-1, -2, ...)
  name: string;
  color: number;            // 0xRRGGBB
  alive: boolean;
  protectedS: number;       // seconds of spawn protection left (0 when none)
  boosting: boolean;
  score: number;
  /** Flat [x0, y0, x1, y1, ...]: head first, then body segments from front to back. */
  segs: number[];
}

/** The whole visible world at one moment. Sent by the host ~SNAP_HZ times a second; also what the renderer draws. */
export interface Snapshot {
  /** Host clock in ms (performance.now() on the host). Used for interpolation only. */
  t: number;
  mowers: MowerSnap[];
  /** Flat [x, y, kind, x, y, kind, ...] kind: 0 = grass, 1 = gold. */
  pellets: number[];
}

/** What a player wants this moment. */
export interface MowerInput {
  angle: number;            // wanted heading, radians
  boost: boolean;
}

/** Something that happened, shown in the HUD feed. */
export interface WorldEvent {
  kind: 'kill' | 'wall' | 'spawn';
  /** Id of the mower that died / spawned. */
  id: number;
  /** For 'kill': id of the mower whose body it hit. */
  by?: number;
  name: string;
  byName?: string;
}
